	// ReserveAddress 地址转保留（冻结不下发）
	// (POST /ledger)
	ReserveAddress(c *gin.Context)
	// BindStatic 地址转静态绑定（MAC 锚定）
	// (POST /ledger/bind)
	BindStatic(c *gin.Context)
